#!/bin/bash
# Wait for the pickup-only server to go idle, restart it (session.py gained wall_at), then run three creative cases with chains.
cd /data/user_data/mbronars/packages/guided_playback; C=/data/user_data/mbronars/.miniconda3/envs/pwm211/bin/python
until curl -s -m 5 http://babel-o9-24:8768/ | grep -q '"busy": false'; do sleep 20; done; echo "server idle $(date)"
kill 849853; sleep 8
CUDA_VISIBLE_DEVICES=0 nohup $C -u bin/serve.py --adapter clean_pickup --ckpt /data/user_data/mbronars/packages/pwm_final/runs/pickup_uncond_x0_regpass_cont200k/checkpoints/final.pt --port 8768 --warmup --warmup_transitions 60 --warmup_episodes 1,1,1,1 --warmup_iterations 1 > logs/serve_pickonly_o924_v3.log 2>&1 &
until grep -q -E "\[serve\] http|Traceback" logs/serve_pickonly_o924_v3.log; do sleep 10; done; echo "server up $(date)"
run(){ N=$1; [ -f runs/pickup/$N/result.json ] || $C bin/client.py http://babel-o9-24:8768/guide "$2" > logs/$N.req.json 2>&1; echo "GEN $N"; bash sweeps/obst_case_chain.sh $N > logs/${N}_chain.log 2>&1; echo "DONE $N"; }
# A: milk carton placed ON TOP of a wooden cabinet (target in the air on its top face; box under the target)
run creative_carton_on_cabinet '{"domain":"pickup","task":"wall","select":"/data/user_data/mbronars/packages/guided_playback/sweeps/assetsweep_select.json","episodes":"11,11,11,11","transitions":60,"steps":10,"offset":"0.30,0,0.196","optimizer":"adam","lr":0.1,"iterations":40,"shell":true,"box_weight":5,"clearance_mm":3,"seed":0,"wall_height":0.196,"wall_thickness":0.196,"wall_width":0.228,"wall_at":1.0,"obstacle_asset":"/data/group_data/katefgroup-ssd/sim_scene_gen/assets/libero/wooden_cabinet/asset_0170","obstacle_rpy":"0,0,90","obstacle_layout":"single","name":"creative_carton_on_cabinet","desc":"milk carton placed on top of a wooden cabinet (libero asset_0170, 19.6 x 22.8 x 19.6 cm) 30 cm away: target = start + (30, 0, +19.6) cm; cabinet box under the target (wall_at 1); Adam lr 0.1, 40 it, shell, box weight 5, clearance 3 mm, pop 4"}'
# B: soda can over a stack of three books lying flat
run creative_can_over_books '{"domain":"pickup","task":"wall","select":"/data/user_data/mbronars/packages/guided_playback/sweeps/assetsweep_select.json","episodes":"13,13,13,13","transitions":60,"steps":10,"offset":"0.30,0.04,0","optimizer":"adam","lr":0.1,"iterations":40,"shell":true,"box_weight":10,"clearance_mm":10,"seed":0,"wall_height":0.106,"wall_thickness":0.149,"wall_width":0.397,"obstacle_asset":"/data/group_data/katefgroup-ssd/sim_scene_gen/assets/libero/book/asset_0004","obstacle_rpy":"90,0,0","obstacle_layout":"rowstack:3:3","name":"creative_can_over_books","desc":"soda can over a ROW of three stacks of three books lying flat (libero book asset_0004 x9: 14.9 deep x 39.7 long x 10.6 cm high) midway, target +30 cm x +4 cm y on the ground; Adam lr 0.1, 40 it, shell, wall weight 10, clearance 10 mm, pop 4"}'
# C: water bottle over a basket to a target 10 cm in the air
run creative_bottle_over_basket '{"domain":"pickup","task":"wall","select":"/data/user_data/mbronars/packages/guided_playback/sweeps/assetsweep_select.json","episodes":"16,16,16,16","transitions":60,"steps":10,"offset":"0.30,-0.04,0.10","optimizer":"adam","lr":0.1,"iterations":40,"shell":true,"box_weight":10,"clearance_mm":10,"seed":0,"wall_height":0.127,"wall_thickness":0.172,"wall_width":0.170,"obstacle_asset":"/data/group_data/katefgroup-ssd/sim_scene_gen/assets/libero/basket/asset_0050","obstacle_rpy":"0,0,0","obstacle_layout":"single","name":"creative_bottle_over_basket","desc":"water bottle over a basket (libero asset_0050, 17.2 x 17.0 x 12.7 cm) midway, target +30 cm x -4 cm y and 10 cm in the air; Adam lr 0.1, 40 it, shell, wall weight 10, clearance 10 mm, pop 4"}'
echo CREATIVE_DONE
